"use client";

import Link from "next/link";
import {
  ApiError,
  Feral,
  getApiErrorMessage,
  getMonstros,
  getMyFerais,
  Monstro,
} from "@/lib/api";
import { usePathname, useRouter } from "next/navigation";
import { useEffect, useState } from "react";

const API_ASSET_URL =
  process.env.NEXT_PUBLIC_API_URL ?? "https://poas-wilderfeast.onrender.com";

const profileAvatar =
  "https://ddragon.leagueoflegends.com/cdn/img/champion/splash/Qiyana_0.jpg";

function resolveApiImage(imageUrl: string | null, fallback: string) {
  if (!imageUrl) {
    return fallback;
  }

  try {
    return new URL(imageUrl, `${API_ASSET_URL}/`).toString();
  } catch {
    return fallback;
  }
}

const images = {
  toad: "data:image/png;base64,",
  avatar: "data:image/png;base64,",
  cleaver: "data:image/png;base64,",
  ember: "data:image/png;base64,",
};

const icons = {
  bestiary: "data:image/svg+xml;base64,",
  character: "data:image/svg+xml;base64,",
  cold: "data:image/svg+xml;base64,",
  dice: "data:image/svg+xml;base64,",
  edible: "data:image/svg+xml;base64,",
  harvestOne: "data:image/svg+xml;base64,",
  harvestTwo: "data:image/svg+xml;base64,",
  home: "data:image/svg+xml;base64,",
  logout: "data:image/svg+xml;base64,",
  profile: "data:image/svg+xml;base64,",
  slashing: "data:image/svg+xml;base64,",
  spicy: "data:image/svg+xml;base64,",
  swamp: "data:image/svg+xml;base64,",
  utensils: "data:image/svg+xml;base64,",
  volcanic: "data:image/svg+xml;base64,",
  water: "data:image/svg+xml;base64,",
};

type MonsterCardProps = {
  harvest: string;
  harvestLabel?: string;
  harvestIcon: string;
  href: string;
  image: string;
  imageClassName?: string;
  name: string;
  tags: Array<{ icon: string; label: string }>;
  threat: string;
  threatLevel: "low" | "high";
  weakness: string;
  weaknessLabel?: string;
  weaknessIcon: string;
};

function MonsterCard({
  harvest,
  harvestLabel = "Coleta",
  harvestIcon,
  href,
  image,
  imageClassName = "",
  name,
  tags,
  threat,
  threatLevel,
  weakness,
  weaknessLabel = "Fraqueza",
  weaknessIcon,
}: MonsterCardProps) {
  return (
    <Link className="home-monster-card" href={href}>
      <header>
        <h3>{name}</h3>
        <span className={`threat threat-${threatLevel}`}>{threat}</span>
      </header>

      <div className="monster-illustration">
        <img className={imageClassName} src={image} alt={name} />
      </div>

      <div className="monster-details">
        <div className="monster-tags">
          {tags.map((tag) => (
            <span key={tag.label}>
              <img src={tag.icon} alt="" />
              {tag.label}
            </span>
          ))}
        </div>

        <div className="monster-facts">
          <div>
            <span>{weaknessLabel}</span>
            <strong className="fact-weakness">
              <img src={weaknessIcon} alt="" />
              {weakness}
            </strong>
          </div>
          <div>
            <span>{harvestLabel}</span>
            <strong className="fact-harvest">
              <img src={harvestIcon} alt="" />
              {harvest}
            </strong>
          </div>
        </div>
      </div>
    </Link>
  );
}

export default function Home() {
  const pathname = usePathname();
  const router = useRouter();
  const isCharacterSheets = pathname === "/fichas";
  const [ferais, setFerais] = useState<Feral[]>([]);
  const [monstros, setMonstros] = useState<Monstro[]>([]);
  const [apiError, setApiError] = useState("");
  const [loadingApi, setLoadingApi] = useState(true);
  const [userName, setUserName] = useState("NOME DO FERAL");

  useEffect(() => {
    const savedUser = localStorage.getItem("wilderfeast_user");
    if (savedUser) {
      try {
        const user = JSON.parse(savedUser) as {
          email?: string;
          nome?: string;
        };
        const savedName = user.nome ?? user.email?.split("@")[0];
        if (savedName) {
          setUserName(savedName.toUpperCase());
        }
      } catch {
        localStorage.removeItem("wilderfeast_user");
      }
    }

    let active = true;
    setLoadingApi(true);
    setApiError("");

    async function loadPageData() {
      try {
        if (isCharacterSheets) {
          const data = await getMyFerais();
          if (active) {
            setFerais(data);
          }
        } else {
          const data = await getMonstros();
          if (active) {
            setMonstros(data);
          }
        }
      } catch (error) {
        if (error instanceof ApiError && error.status === 401) {
          await fetch("/api/session", { method: "DELETE" });
          localStorage.removeItem("wilderfeast_user");
          router.replace(`/login?next=${encodeURIComponent(pathname)}`);
          return;
        }

        if (active) {
          setApiError(
            getApiErrorMessage(error, "Não foi possível carregar os dados."),
          );
        }
      } finally {
        if (active) {
          setLoadingApi(false);
        }
      }
    }

    void loadPageData();

    return () => {
      active = false;
    };
  }, [isCharacterSheets, pathname, router]);

  async function logout() {
    await fetch("/api/session", { method: "DELETE" });
    localStorage.removeItem("wilderfeast_user");
    router.replace("/login");
    router.refresh();
  }

  const apiCards: MonsterCardProps[] = isCharacterSheets
    ? ferais.map((feral, index) => ({
        harvest: feral.especialidade ?? "Não definida",
        harvestIcon: icons.harvestOne,
        harvestLabel: "Especialidade",
        href: `/fichas/${feral.id}`,
        image: resolveApiImage(
          feral.imagem_url,
          images[index % 2 ? "ember" : "toad"],
        ),
        imageClassName: index % 2 ? "ember-image" : "toad-image",
        name: feral.nome.toUpperCase(),
        tags: [
          {
            icon: icons.character,
            label: feral.titulo ?? "Sem título",
          },
          {
            icon: icons.edible,
            label: feral.voce_e ?? "Feral",
          },
        ],
        threat: feral.titulo ?? "Feral",
        threatLevel: index % 2 ? "high" : "low",
        weakness: `${feral.vigor_atual} / ${feral.vigor_max}`,
        weaknessIcon: icons.cold,
        weaknessLabel: "Vigor",
      }))
    : monstros.slice(0, 2).map((monstro, index) => ({
        harvest: `${monstro.vigor_atual} / ${monstro.vigor_base}`,
        harvestIcon: icons.harvestTwo,
        harvestLabel: "Vigor",
        href: `/bestiario/${monstro.id}`,
        image: images[index % 2 ? "ember" : "toad"],
        imageClassName: index % 2 ? "ember-image" : "toad-image",
        name: monstro.nome.toUpperCase(),
        tags: [
          {
            icon: icons.swamp,
            label: monstro.habitat ?? "Habitat desconhecido",
          },
          {
            icon: icons.edible,
            label: monstro.dieta ?? "Dieta desconhecida",
          },
        ],
        threat: `Categoria: ${monstro.categoria}`,
        threatLevel: monstro.categoria === "Jovem" ? "low" : "high",
        weakness: monstro.alvos ?? "Não informado",
        weaknessIcon: icons.water,
        weaknessLabel: "Alvos",
      }));

  const apiStatus = loadingApi
    ? "Carregando dados da API..."
    : apiError
      ? apiError
      : apiCards.length === 0
        ? isCharacterSheets
          ? "Nenhuma ficha cadastrada."
          : "Nenhum monstro cadastrado na API."
        : "";

  return (
    <div
      className={`home-dashboard${
        isCharacterSheets ? " character-sheets-dashboard" : ""
      }`}
    >
      <aside className="home-sidebar">
        <div className="home-user">
          <span className="home-avatar">
            <img src={profileAvatar} alt="Qiyana" />
          </span>
          <strong>{userName}</strong>
        </div>

        <nav className="home-navigation" aria-label="Navegação principal">
          <Link className={isCharacterSheets ? "" : "active"} href="/">
            <img src={icons.home} alt="" />
            <span>Início</span>
          </Link>
          <Link className={isCharacterSheets ? "active" : ""} href="/fichas">
            <img src={icons.character} alt="" />
            <span>Fichas de Personagem</span>
          </Link>
          <Link href={isCharacterSheets ? "/#utensils" : "#utensils"}>
            <img src={icons.utensils} alt="" />
            <span>Utensílios</span>
          </Link>
          <Link href="/bestiario">
            <img src={icons.bestiary} alt="" />
            <span>Bestiário</span>
          </Link>
          <Link href="/dados">
            <img src={icons.dice} alt="" />
            <span>Rolagem de Dados</span>
          </Link>
        </nav>

        <div className="home-sidebar-actions">
          <Link href="/dados">
            <img src={icons.profile} alt="" />
            <span>Perfil</span>
          </Link>
          <button onClick={logout} type="button">
            <img src={icons.logout} alt="" />
            <span>Sair</span>
          </button>
        </div>
      </aside>

      <main
        className={`home-content${
          isCharacterSheets ? " character-sheets-content" : ""
        }`}
      >
        <section
          className={`home-section${
            isCharacterSheets ? " character-sheets-section" : ""
          }`}
        >
          <div className="home-section-heading">
            <h1>{isCharacterSheets ? "Fichas" : "Bestiário"}</h1>
          </div>

          {isCharacterSheets && (
            <Link className="character-create-button" href="/fichas/novo">
              CRIAR
            </Link>
          )}

          <div className="monster-grid">
            {apiCards.map((card) => (
              <MonsterCard key={card.href} {...card} />
            ))}
          </div>

          {apiStatus && (
            <p className="api-status" role={apiError ? "alert" : "status"}>
              {apiStatus}
            </p>
          )}
        </section>

        {!isCharacterSheets && (
          <section className="home-section utensils-section" id="utensils">
            <div className="home-section-heading utensils-heading">
              <h2>Utensílios</h2>
            </div>

            <article className="utensil-card">
              <div className="utensil-photo-wrap">
                <div className="utensil-photo">
                  <img src={images.cleaver} alt="Cutelo de Ferro" />
                </div>
              </div>

              <div className="utensil-details">
                <h3>CUTELO DE FERRO</h3>

                <div className="utensil-stats">
                  <strong>3 POTENTE</strong>
                  <span>2 PRECISO</span>
                  <span className="utensil-type">
                    <img src={icons.slashing} alt="" />
                    Cortante
                  </span>
                </div>

                <div className="durability">
                  <div>
                    <strong>DURABILIDADE</strong>
                    <span>4 / 5</span>
                  </div>
                  <div className="durability-track">
                    <i />
                  </div>
                </div>
              </div>
            </article>
          </section>
        )}
      </main>
    </div>
  );
}
